0 X 120 G","origem_cod":"410","familia_cod":"41009","agrupamento_erp_valor":"P801"},"antes":null},{"codigo_produto":"3752695U","novo":true,"dados":{"codigo_produto":"3752695U","descricao":"CATTE BOMBOM CREMINO 120 G UN","origem_cod":"515","familia_cod":"51508"},"antes":null},{"codigo_produto":"3764638","novo":true,"dados":{"codigo_produto":"3764638","descricao":"CATTE BOMBOM CHOCOLATE AO LEITE COM RECHEIO AVELA 6 X 240 G","origem_cod":"410","familia_cod":"41009"},"antes":null}]$payload$::jsonb;
  v_metadata constant jsonb := $metadata${"fase":"3.4","identificador_lote":"FASE_3_4_9dfb2843-5bcb-4159-8a2a-a59051276a27","hash_arquivo_sha256":"ea5092e92e9b843f341545837f6618998072dc2c533cc837d1807ce7f69ef6da","hash_contexto_sha256":"c2660e76d861b7ad56484f16ffe152e214585abfaf4866e46681de11f3aacd18","hash_manifesto_sha256":"16b0250d89cbeb8fede57a14defa2a460173270952e754428e55357809817fe2","autorizacao":"Pedido humano FASE 3.4: executar as 423 propostas somente apos revalidacao integral; arquivo anexado ee6fa66e-78f9-47c9-9b09-ed8b0a3541ef","aba":"casdatromestrexd","agrupamento_coluna":"Agrup. Prod.","agrupamento_coluna_excel":"Q","propostas_autorizadas":423,"sem_reconciliacao_operacional":true,"protegidas_antes":{"dicionario_produtos":{"registros":6113,"fingerprint":"1555ee693aabad7d5e8536a36666721b"},"mapa_produtos":{"registros":292,"fingerprint":"8769a09b104e42e3a996b07fa6574f76"},"historico_custos":{"registros":1370,"fingerprint":"a4de7e0aa918697373e00a0423ac4b70"},"apontamentos_op":{"registros":704,"fingerprint":"b576ac931683bfac99dd1df1794d453a"},"categorias_origem":{"registros":50,"fingerprint":"603925b56407a96870fb064123eb8860"},"categorias_familia":{"registros":38,"fingerprint":"04b3645662df0f79ac18e9880d832592"},"categorias_agrupamento":{"registros":34,"fingerprint":"3b14395a70b6cad47474c3fa160e16db"}}}$metadata$::jsonb;
  v_id bigint;
  v_instante timestamptz := clock_timestamp();
  v_antes jsonb;
  v_esperado jsonb;
  v_protegidas_antes jsonb := '{}'::jsonb;
  v_protegidas_depois jsonb := '{}'::jsonb;
  v_tabela text;
  v_fp text;
  v_quantidade bigint;
  v_inseridos integer := 0;
  v_atualizados integer := 0;
  v_faltantes integer;
  v_excedentes integer;
  v_erro text;
  v_sqlstate text;
begin
  -- Dupla guarda: conteudo integral e existencia de qualquer lote anterior.
  select count(*), md5(coalesce(string_agg(to_jsonb(d)::text, E'\n' order by to_jsonb(d)::text), '')),
    jsonb_agg(to_jsonb(d) order by codigo_produto)
  into v_quantidade, v_fp, v_antes from public.dicionario_master_produtos d;
  if v_quantidade <> 5603 or v_fp <> '24d9ed91f46baa353d2bdae74859c030'
    or exists(select 1 from public.log_importacao_cadastro_mestre) then
    raise exception 'REVALIDACAO BLOQUEADA: Master ou log mudou; nenhuma escrita autorizada';
  end if;
  if exists(select 1 from pg_trigger where not tgisinternal and tgenabled <> 'D'
    and tgrelid in ('public.dicionario_master_produtos'::regclass,
      'public.log_importacao_cadastro_mestre'::regclass)) then
    raise exception 'REVALIDACAO BLOQUEADA: trigger inesperado no Master/log';
  end if;
  if jsonb_array_length(v_patches) <> 415
    or (select count(*) from jsonb_array_elements(v_patches) p where (p->>'novo')::boolean) <> 103
    or (select count(distinct p->>'codigo_produto') from jsonb_array_elements(v_patches) p) <> 415
    or (select count(*) from jsonb_array_elements(v_patches) p where not (p->>'novo')::boolean and p->'dados' ? 'descricao') <> 11
    or (select count(*) from jsonb_array_elements(v_patches) p where not (p->>'novo')::boolean and p->'dados' ? 'agrupamento_erp_valor') <> 309 then
    raise exception 'REVALIDACAO BLOQUEADA: contagens do payload nao conferem';
  end if;
  if exists(select 1 from jsonb_array_elements(v_patches) p
    left join public.dicionario_master_produtos d on d.codigo_produto=p->>'codigo_produto'
    where ((p->>'novo')::boolean and d.codigo_produto is not null)
      or (not (p->>'novo')::boolean and (d.codigo_produto is null or to_jsonb(d) is distinct from p->'antes'))) then
    raise exception 'REVALIDACAO BLOQUEADA: produto novo existente ou imagem anterior divergente';
  end if;
  if exists(select 1 from jsonb_array_elements(v_patches) p,
    lateral jsonb_each(p->'dados') e where e.value='null'::jsonb
      or ((p->>'novo')::boolean and e.key not in ('codigo_produto','descricao','origem_cod','familia_cod','agrupamento_erp_valor'))
      or (not (p->>'novo')::boolean and e.key not in ('descricao','agrupamento_erp_valor'))) then
    raise exception 'REVALIDACAO BLOQUEADA: campo fora do contrato ou NULL proposto';
  end if;
  foreach v_tabela in array array['apontamentos_op','categorias_agrupamento','categorias_familia',
    'categorias_origem','dicionario_produtos','historico_custos','mapa_produtos'] loop
    execute format('select count(*), md5(coalesce(string_agg(to_jsonb(d)::text, E''\n'' order by to_jsonb(d)::text), '''')) from public.%I d',v_tabela)
      into v_quantidade,v_fp;
    v_protegidas_antes := v_protegidas_antes || jsonb_build_object(v_tabela,
      jsonb_build_object('registros',v_quantidade,'fingerprint',v_fp));
  end loop;
  if v_protegidas_antes is distinct from v_metadata->'protegidas_antes' then
    raise exception 'REVALIDACAO BLOQUEADA: tabela protegida mudou antes da execucao';
  end if;

  insert into public.log_importacao_cadastro_mestre
    (arquivo_nome,tipo_arquivo,arquivo_hash,identificador_lote,fonte_sistema,status,total_registros,metadados_origem)
  values ('casdatromestrexd.xlsm','XLSM',v_metadata->>'hash_arquivo_sha256',
    v_metadata->>'identificador_lote','ERP','processando',853,
    v_metadata || jsonb_build_object('imagens_anteriores_atualizados',
      (select jsonb_agg(p->'antes') from jsonb_array_elements(v_patches) p where not (p->>'novo')::boolean)))
  returning id into v_id;

  -- Subtransacao: uma falha desfaz todo o Master, preservando um log real de falha.
  begin
    insert into public.dicionario_master_produtos
      (codigo_produto,descricao,origem_cod,familia_cod,agrupamento_erp_valor,
        agrupamento_erp_importacao_id,ultima_importacao_cadastro_mestre_id,criado_em,atualizado_em)
    select p->>'codigo_produto',p->'dados'->>'descricao',p->'dados'->>'origem_cod',
      p->'dados'->>'familia_cod',p->'dados'->>'agrupamento_erp_valor',
      case when p->'dados' ? 'agrupamento_erp_valor' then v_id else null end,
      v_id,v_instante,v_instante
    from jsonb_array_elements(v_patches) p where (p->>'novo')::boolean;
    get diagnostics v_inseridos = row_count;

    update public.dicionario_master_produtos d
    set descricao = case when p->'dados' ? 'descricao' then p->'dados'->>'descricao' else d.descricao end,
      agrupamento_erp_valor = case when p->'dados' ? 'agrupamento_erp_valor' then p->'dados'->>'agrupamento_erp_valor' else d.agrupamento_erp_valor end,
      agrupamento_erp_importacao_id = case when p->'dados' ? 'agrupamento_erp_valor' then v_id else d.agrupamento_erp_importacao_id end,
      ultima_importacao_cadastro_mestre_id = v_id,
      atualizado_em = v_instante
    from jsonb_array_elements(v_patches) p
    where not (p->>'novo')::boolean and d.codigo_produto=p->>'codigo_produto';
    get diagnostics v_atualizados = row_count;

    -- Imagem esperada independente: originais + patches autorizados + proveniencia.
    select jsonb_agg(linha order by linha->>'codigo_produto') into v_esperado from (
      select b || coalesce(p->'dados','{}'::jsonb)
        || case when p is null then '{}'::jsonb else
          jsonb_build_object('ultima_importacao_cadastro_mestre_id',v_id,'atualizado_em',v_instante)
          || case when p->'dados' ? 'agrupamento_erp_valor' then
            jsonb_build_object('agrupamento_erp_importacao_id',v_id) else '{}'::jsonb end end as linha
      from jsonb_array_elements(v_antes) b
      left join jsonb_array_elements(v_patches) p on p->>'codigo_produto'=b->>'codigo_produto'
      union all
      select (p->'dados') || jsonb_build_object('agrupamento_erp_valor',p->'dados'->>'agrupamento_erp_valor',
        'agrupamento_erp_importacao_id',case when p->'dados' ? 'agrupamento_erp_valor' then v_id else null end,
        'ultima_importacao_cadastro_mestre_id',v_id,'criado_em',v_instante,'atualizado_em',v_instante)
      from jsonb_array_elements(v_patches) p where (p->>'novo')::boolean
    ) esperado;
    select count(*) into v_faltantes from (
      select value from jsonb_array_elements(v_esperado)
      except select to_jsonb(d) from public.dicionario_master_produtos d
    ) x;
    select count(*) into v_excedentes from (
      select to_jsonb(d) from public.dicionario_master_produtos d
      except select value from jsonb_array_elements(v_esperado)
    ) x;
    if v_inseridos <> 103 or v_atualizados <> 312 or v_faltantes <> 0 or v_excedentes <> 0
      or (select count(*) from public.dicionario_master_produtos) <> 5706 then
      raise exception 'VALIDACAO FALHOU: contagens ou EXCEPT integral divergente';
    end if;
    foreach v_tabela in array array['apontamentos_op','categorias_agrupamento','categorias_familia',
      'categorias_origem','dicionario_produtos','historico_custos','mapa_produtos'] loop
      execute format('select count(*), md5(coalesce(string_agg(to_jsonb(d)::text, E''\n'' order by to_jsonb(d)::text), '''')) from public.%I d',v_tabela)
        into v_quantidade,v_fp;
      v_protegidas_depois := v_protegidas_depois || jsonb_build_object(v_tabela,
        jsonb_build_object('registros',v_quantidade,'fingerprint',v_fp));
    end loop;
    if v_protegidas_depois is distinct from v_protegidas_antes then
      raise exception 'VALIDACAO FALHOU: tabela protegida divergente';
    end if;
    update public.log_importacao_cadastro_mestre
    set status='concluido',finalizado_em=clock_timestamp(),registros_processados=853,
      registros_inseridos=v_inseridos,registros_atualizados=v_atualizados,registros_erro=0,
      metadados_origem=metadados_origem || jsonb_build_object('validacao',jsonb_build_object(
        'master_final',5706,'except_esperado_atual',v_faltantes,'except_atual_esperado',v_excedentes,
        'protegidas_depois',v_protegidas_depois,'atualizacoes_por_campo',320,
        'descricoes_atualizadas',11,'agrupamentos_existentes',309,'agrupamentos_novos',33,
        'agrupamentos_total',342,'master_preservados',5291,'fora_conjunto_preservados',4853,
        'elegiveis_existentes_preservados',438,'familias_pendentes',686,'familias_resolvidas',167))
    where id=v_id;
  exception when others then
    get stacked diagnostics v_erro = message_text, v_sqlstate = returned_sqlstate;
    update public.log_importacao_cadastro_mestre
    set status='falhou',finalizado_em=clock_timestamp(),registros_processados=0,
      registros_inseridos=0,registros_atualizados=0,registros_erro=415,
      erros=jsonb_build_array(jsonb_build_object('sqlstate',v_sqlstate,'mensagem',v_erro,
        'master_revertido_pela_subtransacao',true))
    where id=v_id;
  end;
end;
$execucao$;
commit;
